def delRecBy(name):
    if not checkNameSafe(name):
        return False
    try:
        path = appConf()
        content = yf.readFile(path)

        reclist = getRecListData()
        ret_list_len = len(reclist)
        is_end = False
        next_name = ''
        for x in range(ret_list_len):
            tmp = reclist[x]
            if tmp['name'] == name:

                secrets_file = tmp['secrets file']
                tp = os.path.dirname(secrets_file)
                if os.path.exists(tp):
                    yf.removeDir(tp)

                if x + 1 == ret_list_len:
                    is_end = True
                else:
                    next_name = reclist[x + 1]['name']
        reg = ''
        if is_end:
            reg = r'\[' + name + r'\]\s*(.*)'
        else:
            reg = r'\\[' + name + r'\]\s*(.*)\s*\[' + next_name + r'\]'

        conre = re.search(reg,  content, re.S)
        content = content.replace("[" + name + "]\n" + conre.groups()[0], '')
        yf.writeFile(path, content)
    except Exception as e:
        return False
    return True


